/**
 * Motion tokens — the single source of truth for animation.
 *
 * Components never hardcode durations, easings or springs; they read the
 * semantic tokens below (via CSS variables emitted by `createTheme`) or call
 * the active `adapter` for imperative animations.
 *
 * Switch engines by changing the adapter import:
 *   - "@/registry/lib/adapters/css"     Web Animations + CSS transitions (no dependency)
 *   - "@/registry/lib/adapters/motion"  Motion (formerly Framer Motion)
 *   - "@/registry/lib/adapters/gsap"    GSAP
 *   - "./my-motion"             your own adapter implementing `MotionAdapter`
 *
 * The `fluid` scheme needs the Motion or GSAP engine: it reads velocity every
 * frame to stretch and wobble shapes. With the CSS engine it falls back to
 * `expressive`.
 */
import type { Spring } from "@/registry/lib/spring";

export { adapter } from "@/registry/lib/adapters/css";

export type MotionScheme = "standard" | "expressive" | "fluid";
export type SpringType = "spatial" | "effects";
export type SpringSpeed = "fast" | "default" | "slow";

export type SpringTokens = Record<SpringType, Record<SpringSpeed, Spring>>;

/**
 * Material 3 Expressive motion schemes.
 * Spatial springs move things (position, size, shape) and may overshoot;
 * effects springs fade and recolor, and never overshoot.
 */
export const springs: Record<MotionScheme, SpringTokens> = {
  expressive: {
    spatial: {
      fast: { dampingRatio: 0.6, stiffness: 800 },
      default: { dampingRatio: 0.8, stiffness: 380 },
      slow: { dampingRatio: 0.8, stiffness: 200 },
    },
    effects: {
      fast: { dampingRatio: 1, stiffness: 3800 },
      default: { dampingRatio: 1, stiffness: 1600 },
      slow: { dampingRatio: 1, stiffness: 800 },
    },
  },
  /*
   * Fluid: soft, low-stiffness springs that glide into place with very little
   * overshoot. The liveliness lives in the shape instead (see FluidTokens):
   * it stretches with speed, splats when it stops, and jiggles back.
   */
  fluid: {
    spatial: {
      fast: { dampingRatio: 0.78, stiffness: 420 },
      default: { dampingRatio: 0.82, stiffness: 200 },
      slow: { dampingRatio: 0.86, stiffness: 110 },
    },
    effects: {
      fast: { dampingRatio: 1, stiffness: 1400 },
      default: { dampingRatio: 1, stiffness: 700 },
      slow: { dampingRatio: 1, stiffness: 360 },
    },
  },
  standard: {
    spatial: {
      fast: { dampingRatio: 0.9, stiffness: 1400 },
      default: { dampingRatio: 0.9, stiffness: 700 },
      slow: { dampingRatio: 0.9, stiffness: 300 },
    },
    effects: {
      fast: { dampingRatio: 1, stiffness: 3800 },
      default: { dampingRatio: 1, stiffness: 1600 },
      slow: { dampingRatio: 1, stiffness: 800 },
    },
  },
};

/** Duration + easing tokens for transitions that are not spring-based. */
export const durations = {
  short: 100,
  medium: 250,
  long: 450,
  "extra-long": 700,
} as const;

export const easings = {
  standard: "cubic-bezier(0.2, 0, 0, 1)",
  "standard-decelerate": "cubic-bezier(0, 0, 0, 1)",
  "standard-accelerate": "cubic-bezier(0.3, 0, 1, 1)",
  emphasized: "cubic-bezier(0.2, 0, 0, 1)",
  "emphasized-decelerate": "cubic-bezier(0.05, 0.7, 0.1, 1)",
  "emphasized-accelerate": "cubic-bezier(0.3, 0, 0.8, 0.15)",
} as const;

/**
 * How fluid motion bends shapes. Speed is measured in element-sizes per
 * second, so small and large elements deform alike.
 */
export interface FluidTokens {
  /** Stretch per (size / second) of speed along the direction of travel. */
  viscosity: number;
  /** Upper bound on stretch; 0.3 = up to 30% longer and ~23% thinner. */
  maxStretch: number;
  /** How far a press squashes an element (0.06 = 6% wider, ~6% shorter). */
  squash: number;
  /** Damping ratio of the shape's jelly wobble: after moving, pressing or popping (lower = wobblier). */
  wobble: number;
}

export const fluid: FluidTokens = { viscosity: 0.05, maxStretch: 0.3, squash: 0.07, wobble: 0.3 };

export interface MotionTokens {
  /** Scheme used when a component has no `motion` prop. */
  scheme: MotionScheme;
  springs: Record<MotionScheme, SpringTokens>;
  durations: Record<string, number>;
  easings: Record<string, string>;
  fluid: FluidTokens;
}

export const defaultMotion: MotionTokens = { scheme: "expressive", springs, durations, easings, fluid };

/** Resolve a spring token, e.g. `getSpring("expressive", "spatial", "fast")`. */
export function getSpring(scheme: MotionScheme, type: SpringType, speed: SpringSpeed = "default"): Spring {
  return springs[scheme][type][speed];
}

/**
 * Spring physics shared by every motion adapter.
 *
 * Springs are described the way Material does: a damping ratio and a
 * stiffness (mass = 1). From that we can solve the position at any time,
 * find when it settles, and sample it into a CSS `linear()` easing.
 */

export interface Spring {
  /** 1 = critically damped (no overshoot), < 1 = bouncy. */
  dampingRatio: number;
  stiffness: number;
}

const EPSILON = 0.001;

/** Normalized position (0 → 1) of a spring released from rest at time `t` seconds. */
export function springAt({ dampingRatio: zeta, stiffness }: Spring, t: number): number {
  const omega = Math.sqrt(stiffness);
  if (zeta < 1) {
    const omegaD = omega * Math.sqrt(1 - zeta * zeta);
    return 1 - Math.exp(-zeta * omega * t) * (Math.cos(omegaD * t) + ((zeta * omega) / omegaD) * Math.sin(omegaD * t));
  }
  if (zeta === 1) {
    return 1 - Math.exp(-omega * t) * (1 + omega * t);
  }
  const s = omega * Math.sqrt(zeta * zeta - 1);
  const r1 = -zeta * omega + s;
  const r2 = -zeta * omega - s;
  return 1 - (r2 * Math.exp(r1 * t) - r1 * Math.exp(r2 * t)) / (r2 - r1);
}

/** Time in ms until the spring stays within `EPSILON` of its target. */
export function springDuration(spring: Spring): number {
  const step = 1 / 1000;
  let lastOutside = 0;
  for (let t = 0; t < 10; t += step) {
    if (Math.abs(1 - springAt(spring, t)) > EPSILON) lastOutside = t;
    else if (t - lastOutside > 0.1) break;
  }
  return Math.round((lastOutside + step) * 1000);
}

/** Easing function over normalized progress (0 → 1) of `springDuration`. */
export function springEasing(spring: Spring): (progress: number) => number {
  const seconds = springDuration(spring) / 1000;
  return (progress) => (progress >= 1 ? 1 : springAt(spring, progress * seconds));
}

const round = (n: number) => Math.round(n * 10000) / 10000;

/** CSS `linear()` easing that approximates the spring, ending exactly at 1. */
export function springToLinear(spring: Spring, samples = 40): string {
  const ease = springEasing(spring);
  const points: number[] = [];
  for (let i = 0; i <= samples; i++) points.push(round(ease(i / samples)));
  points[points.length - 1] = 1;
  return `linear(${points.join(", ")})`;
}

export interface SpringState {
  value: number;
  velocity: number;
}

/**
 * Advance a spring by `dt` seconds toward `target` (semi-implicit Euler with
 * ~1ms substeps, stable for every Expressive spring). Mutates and returns `state`.
 */
export function stepSpring(state: SpringState, target: number, { dampingRatio, stiffness }: Spring, dt: number): SpringState {
  const damping = 2 * dampingRatio * Math.sqrt(stiffness);
  const steps = Math.max(1, Math.ceil(dt / 0.001));
  const h = dt / steps;
  for (let i = 0; i < steps; i++) {
    const acceleration = -stiffness * (state.value - target) - damping * state.velocity;
    state.velocity += acceleration * h;
    state.value += state.velocity * h;
  }
  return state;
}

/** At rest: close to the target and barely moving (relative to the travel). */
export function springSettled(state: SpringState, target: number, travel: number): boolean {
  const scale = Math.max(Math.abs(travel), 1e-3);
  return Math.abs(state.value - target) < scale * 0.002 && Math.abs(state.velocity) < scale * 0.02;
}

import type { Spring } from "@/registry/lib/spring";

export type Keyframes = Record<string, Array<string | number>>;

export interface AnimateOptions {
  spring: Spring;
  delay?: number;
}

export interface MotionControls {
  finished: Promise<void>;
  cancel(): void;
}

export interface FluidSpringOptions {
  from: number;
  to: number;
  /** Starting velocity in units per second (carry it over when retargeting). */
  velocity?: number;
  spring: Spring;
  /** Called every frame with the current value and velocity (units/s). */
  onUpdate: (value: number, velocity: number) => void;
  onComplete?: () => void;
}

export interface FluidSpring {
  stop(): void;
}

/**
 * Velocity-aware springs for the `fluid` scheme. Engines that can report
 * velocity every frame (Motion, GSAP) provide this; CSS can't.
 */
export interface FluidDriver {
  spring(options: FluidSpringOptions): FluidSpring;
}

/**
 * Contract every motion engine implements. Write your own (`my-motion.ts`)
 * and export it as `adapter` from `tokens/motion.ts`.
 */
export interface MotionAdapter {
  name: string;
  animate(element: Element, keyframes: Keyframes, options: AnimateOptions): MotionControls;
  /** Present only on engines that support the `fluid` scheme. */
  fluid?: FluidDriver;
}

import { springDuration, springToLinear } from "@/registry/lib/spring";
import type { MotionAdapter } from "./types";

/** Default engine: Web Animations API with spring-sampled `linear()` easing. */
export const adapter: MotionAdapter = {
  name: "css",
  animate(element, keyframes, { spring, delay = 0 }) {
    if (typeof element.animate !== "function") {
      return { finished: Promise.resolve(), cancel() {} };
    }
    const animation = element.animate(keyframes as PropertyIndexedKeyframes, {
      duration: springDuration(spring),
      easing: springToLinear(spring),
      delay,
      fill: "forwards",
    });
    return {
      finished: animation.finished.then(
        () => undefined,
        () => undefined,
      ),
      cancel: () => animation.cancel(),
    };
  },
};

"use client";

import * as React from "react";
import { type MotionScheme, type SpringSpeed, type SpringType, adapter, defaultMotion, getSpring } from "@/registry/tokens/motion";
import type { Keyframes, MotionAdapter, MotionControls } from "@/registry/lib/adapters/types";
import { useReducedMotion } from "@/registry/lib/use-reduced-motion";

export type MotionProp = MotionScheme | "none";

export interface MotionAnimateOptions {
  type?: SpringType;
  speed?: SpringSpeed;
  delay?: number;
}

/**
 * Override the engine from `tokens/motion.ts` for part of the tree,
 * e.g. `<MotionAdapterContext value={gsapAdapter}>` in tests or demos.
 */
export const MotionAdapterContext = React.createContext<MotionAdapter>(adapter);

const noop: MotionControls = { finished: Promise.resolve(), cancel() {} };

/** The scheme that applies to `element`: the prop, else `--ex-motion-scheme` from the theme. */
function schemeOf(element: Element, motion?: MotionProp): MotionScheme | "none" {
  if (motion) return motion;
  if (typeof getComputedStyle === "undefined") return defaultMotion.scheme;
  const value = getComputedStyle(element).getPropertyValue("--ex-motion-scheme").trim();
  return (value as MotionScheme | "none") || defaultMotion.scheme;
}

/**
 * Imperative animations through the active motion adapter (CSS, Motion, GSAP
 * or your own). Without a `motion` argument the element's own scheme applies.
 * Respects `prefers-reduced-motion` and `motion="none"` by jumping straight to
 * the final keyframe. `fluid` falls back to `expressive` on engines without a
 * fluid driver.
 */
export function useMotion(motion?: MotionProp) {
  const engine = React.useContext(MotionAdapterContext);
  const reducedMotion = useReducedMotion();

  const animate = React.useCallback(
    (element: Element | null, keyframes: Keyframes, { type = "spatial", speed = "default", delay }: MotionAnimateOptions = {}) => {
      if (!element) return noop;
      let scheme = schemeOf(element, motion);
      if (reducedMotion || scheme === "none") {
        const style = (element as HTMLElement).style;
        for (const [property, values] of Object.entries(keyframes)) {
          style.setProperty(property.replace(/[A-Z]/g, (c) => `-${c.toLowerCase()}`), String(values[values.length - 1]));
        }
        return noop;
      }
      if (scheme === "fluid" && !engine.fluid) scheme = "expressive";
      return engine.animate(element, keyframes, { spring: getSpring(scheme, type, speed), delay });
    },
    [reducedMotion, engine, motion],
  );

  /** Whether `element` currently animates with the fluid scheme. */
  const isFluid = React.useCallback(
    (element: Element | null) => Boolean(element && engine.fluid && !reducedMotion && schemeOf(element, motion) === "fluid"),
    [engine, reducedMotion, motion],
  );

  return { animate, isFluid, reducedMotion: reducedMotion || motion === "none", engine: engine.name };
}

"use client";

import * as React from "react";

const query = "(prefers-reduced-motion: reduce)";

function subscribe(callback: () => void) {
  if (typeof window === "undefined" || !window.matchMedia) return () => {};
  const media = window.matchMedia(query);
  media.addEventListener("change", callback);
  return () => media.removeEventListener("change", callback);
}

const getSnapshot = () => (typeof window !== "undefined" && window.matchMedia ? window.matchMedia(query).matches : false);

/** `true` when the user asked the OS for reduced motion. */
export function useReducedMotion(): boolean {
  return React.useSyncExternalStore(subscribe, getSnapshot, () => false);
}

/**
 * Fluid deformation math (pure, engine-agnostic).
 *
 * A moving element stretches along its direction of travel and thins across
 * it, keeping its area, so it reads like a droplet rather than a rigid box.
 * The stretch follows speed through its own underdamped spring, so when the
 * element stops, the shape overshoots into a splat and jiggles back. Speed is
 * normalised by the element's size, so a 24px handle and a 400px dialog
 * deform alike.
 */

import type { FluidTokens } from "@/registry/tokens/motion";
import type { Spring } from "@/registry/lib/spring";

export interface FluidPose {
  /** Translation in px. */
  x: number;
  y: number;
  /** Layout scale (FLIP size changes, or growth when popping in). */
  sx: number;
  sy: number;
  /** Squash: > 0 is wider and shorter, < 0 taller and narrower (area-preserving). */
  squash: number;
}

export interface FluidShape {
  /** Length along `angle` divided by the resting length (1 = round, > 1 stretched, < 1 splatted). */
  stretch: number;
  /** Direction of travel, radians. */
  angle: number;
  /** Lean into horizontal motion, degrees. */
  lean: number;
}

export const restPose = (): FluidPose => ({ x: 0, y: 0, sx: 1, sy: 1, squash: 0 });
export const restShape = (): FluidShape => ({ stretch: 1, angle: 0, lean: 0 });

/** The spring the shape uses to follow speed: soft, and as wobbly as the tokens say. */
export const shapeSpring = (tokens: FluidTokens): Spring => ({ dampingRatio: tokens.wobble, stiffness: 380 });

/** How stretched the shape wants to be at this velocity (px/s), before the jelly spring. */
export function targetStretch(vx: number, vy: number, size: number, tokens: FluidTokens): number {
  const speed = Math.hypot(vx, vy) / Math.max(size, 1);
  return 1 + Math.min(tokens.maxStretch, speed * tokens.viscosity);
}

export function leanFor(vx: number, size: number, tokens: FluidTokens): number {
  return Math.max(-4, Math.min(4, (vx / Math.max(size, 1)) * tokens.viscosity * 12));
}

/** Keep a wobbling stretch inside the same bounds in both directions. */
export function clampStretch(stretch: number, tokens: FluidTokens): number {
  const max = 1 + tokens.maxStretch;
  return Math.min(max, Math.max(1 / max, stretch));
}

const r = (n: number) => Math.round(n * 1000) / 1000;

/** CSS transform for a pose and shape. Returns "" at rest so the element's own styles apply. */
export function poseTransform(pose: FluidPose, shape: FluidShape): string {
  const parts: string[] = [];
  if (Math.abs(pose.x) > 0.01 || Math.abs(pose.y) > 0.01) parts.push(`translate(${r(pose.x)}px, ${r(pose.y)}px)`);
  if (Math.abs(shape.lean) > 0.01) parts.push(`rotate(${r(shape.lean)}deg)`);
  if (Math.abs(shape.stretch - 1) > 0.001) {
    const deg = (shape.angle * 180) / Math.PI;
    parts.push(`rotate(${r(deg)}deg) scale(${r(shape.stretch)}, ${r(1 / shape.stretch)}) rotate(${r(-deg)}deg)`);
  }
  const squashX = 1 + pose.squash;
  const sx = pose.sx * squashX;
  const sy = pose.sy / squashX;
  if (Math.abs(sx - 1) > 0.001 || Math.abs(sy - 1) > 0.001) parts.push(`scale(${r(sx)}, ${r(sy)})`);
  return parts.join(" ");
}

/** Fluid tokens from the element's CSS variables (so themes can tune them). */
export function readFluidTokens(element: Element, fallback: FluidTokens): FluidTokens {
  const style = getComputedStyle(element);
  const read = (name: string, value: number) => {
    const parsed = Number.parseFloat(style.getPropertyValue(name));
    return Number.isFinite(parsed) ? parsed : value;
  };
  return {
    viscosity: read("--ex-fluid-viscosity", fallback.viscosity),
    maxStretch: read("--ex-fluid-max-stretch", fallback.maxStretch),
    squash: read("--ex-fluid-squash", fallback.squash),
    wobble: read("--ex-fluid-wobble", fallback.wobble),
  };
}

"use client";

import * as React from "react";
import { type MotionScheme, defaultMotion, getSpring } from "@/registry/tokens/motion";
import type { FluidDriver, FluidSpring } from "@/registry/lib/adapters/types";
import { type Spring, springSettled, stepSpring } from "@/registry/lib/spring";
import {
  type FluidPose,
  clampStretch,
  leanFor,
  poseTransform,
  readFluidTokens,
  restPose,
  restShape,
  shapeSpring,
  targetStretch,
} from "@/registry/lib/fluid";
import { MotionAdapterContext, type MotionProp } from "@/registry/lib/use-motion";
import { useReducedMotion } from "@/registry/lib/use-reduced-motion";

/*
 * Fluid motion hooks. Each one is inert unless the element's motion scheme
 * (its `motion` prop, else `--ex-motion-scheme` from the theme / data-motion)
 * is "fluid" AND the engine provides a fluid driver (Motion or GSAP).
 * While active, the element gets `data-fluid`, so its classes can hand
 * transform animation over to script with the `fluid:` variant.
 */

let warned = false;

/** The motion scheme that applies to `element`. */
export function resolveScheme(element: Element | null, motion?: MotionProp): MotionScheme | "none" {
  if (motion) return motion;
  if (!element || typeof getComputedStyle === "undefined") return defaultMotion.scheme;
  const value = getComputedStyle(element).getPropertyValue("--ex-motion-scheme").trim();
  return (value as MotionScheme | "none") || defaultMotion.scheme;
}

function useFluidDriver(motion?: MotionProp) {
  const engine = React.useContext(MotionAdapterContext);
  const reducedMotion = useReducedMotion();
  return React.useCallback(
    (element: Element | null): FluidDriver | undefined => {
      if (!element || reducedMotion || resolveScheme(element, motion) !== "fluid") {
        element?.removeAttribute("data-fluid");
        return undefined;
      }
      if (!engine.fluid) {
        if (!warned && typeof console !== "undefined") {
          warned = true;
          console.warn(
            `[expressive] The "fluid" motion scheme needs the Motion or GSAP engine (current: ${engine.name}). Falling back to "expressive".`,
          );
        }
        element.removeAttribute("data-fluid");
        return undefined;
      }
      element.setAttribute("data-fluid", "");
      return engine.fluid;
    },
    [engine, reducedMotion, motion],
  );
}

type Channel = keyof FluidPose;

/**
 * One element's pose, driven by a spring per channel through the engine.
 * Retargeting keeps the current value and velocity, so interrupted motion
 * carries its momentum. The shape (stretch) follows the speed through its own
 * wobbly spring, stepped here every frame until it settles.
 */
class FluidBody {
  pose = restPose();
  private velocity: Record<Channel, number> = { x: 0, y: 0, sx: 0, sy: 0, squash: 0 };
  private springs: Partial<Record<Channel, FluidSpring>> = {};
  private shape = restShape();
  private stretch = { value: 1, velocity: 0 };
  private frame = 0;
  private last = 0;
  private element: HTMLElement;
  private driver: FluidDriver;

  constructor(element: HTMLElement, driver: FluidDriver) {
    this.element = element;
    this.driver = driver;
  }

  setDriver(driver: FluidDriver) {
    this.driver = driver;
  }

  to(channel: Channel, target: number, spring: Spring, { from, velocity }: { from?: number; velocity?: number } = {}) {
    this.springs[channel]?.stop();
    if (from !== undefined) this.pose[channel] = from;
    this.springs[channel] = this.driver.spring({
      from: this.pose[channel],
      to: target,
      velocity: velocity ?? this.velocity[channel],
      spring,
      onUpdate: (value, v) => {
        this.pose[channel] = value;
        this.velocity[channel] = v;
        this.wake();
      },
      onComplete: () => {
        this.velocity[channel] = 0;
        delete this.springs[channel];
        this.wake();
      },
    });
    this.wake();
  }

  stop() {
    for (const spring of Object.values(this.springs)) spring?.stop();
    if (this.frame) cancelAnimationFrame(this.frame);
    this.frame = 0;
    this.springs = {};
    this.pose = restPose();
    this.shape = restShape();
    this.stretch = { value: 1, velocity: 0 };
    this.velocity = { x: 0, y: 0, sx: 0, sy: 0, squash: 0 };
    this.element.style.transform = "";
  }

  private wake() {
    if (this.frame) return;
    this.last = performance.now();
    this.frame = requestAnimationFrame(this.tick);
  }

  private tick = (now: number) => {
    const dt = Math.min(Math.max((now - this.last) / 1000, 0), 0.064);
    this.last = now;
    const tokens = readFluidTokens(this.element, defaultMotion.fluid);
    const size = Math.max(this.element.offsetWidth, this.element.offsetHeight, 1);
    const { x: vx, y: vy } = this.velocity;

    // The shape chases the speed through a jelly spring: stretched while moving,
    // splatted (stretch < 1) for a moment after stopping, then round again.
    if (Math.hypot(vx, vy) > size * 0.05) this.shape.angle = Math.atan2(vy, vx);
    stepSpring(this.stretch, targetStretch(vx, vy, size, tokens), shapeSpring(tokens), dt);
    this.shape.stretch = clampStretch(this.stretch.value, tokens);
    this.shape.lean = leanFor(vx, size, tokens);

    this.element.style.transform = poseTransform(this.pose, this.shape);

    const moving = Object.keys(this.springs).length > 0;
    const settled = !moving && springSettled(this.stretch, 1, tokens.maxStretch);
    if (settled) {
      this.stretch = { value: 1, velocity: 0 };
      this.shape = restShape();
      this.element.style.transform = poseTransform(this.pose, this.shape);
      this.frame = 0;
    } else {
      this.frame = requestAnimationFrame(this.tick);
    }
  };
}

function useBody(ref: React.RefObject<HTMLElement | null>) {
  const body = React.useRef<FluidBody | null>(null);
  React.useEffect(() => () => body.current?.stop(), []);
  return React.useCallback(
    (driver: FluidDriver) => {
      const element = ref.current!;
      if (!body.current) body.current = new FluidBody(element, driver);
      else body.current.setDriver(driver);
      return body.current;
    },
    [ref],
  );
}

/** Run `callback` whenever one of `attributes` changes on the element (before paint). */
function useAttributeChange(ref: React.RefObject<HTMLElement | null>, attributes: string[], callback: () => void) {
  const latest = React.useRef(callback);
  latest.current = callback;
  const key = attributes.join(" ");
  React.useEffect(() => {
    const element = ref.current;
    if (!element || typeof MutationObserver === "undefined") return;
    const observer = new MutationObserver(() => latest.current());
    observer.observe(element, { attributes: true, attributeFilter: key.split(" ") });
    return () => observer.disconnect();
  }, [ref, key]);
}

const jelly = (wobble: number): Spring => ({ dampingRatio: wobble, stiffness: 420 });

/**
 * Press jelly + touch response: squashes on press, wobbles back on release,
 * and gives a small squash impulse when the pointer crosses the element.
 */
export function useFluidPress(ref: React.RefObject<HTMLElement | null>, motion?: MotionProp, enabled = true) {
  const driverFor = useFluidDriver(motion);
  const bodyFor = useBody(ref);

  React.useEffect(() => {
    const element = ref.current;
    if (!element || !enabled) return;
    let pressed = false;
    let entered = false;

    const start = () => {
      const driver = driverFor(element);
      return driver ? bodyFor(driver) : undefined;
    };
    const down = (event: PointerEvent) => {
      if (event.button !== 0) return;
      const body = start();
      if (!body) return;
      pressed = true;
      body.to("squash", readFluidTokens(element, defaultMotion.fluid).squash, getSpring("fluid", "spatial", "fast"));
    };
    const release = () => {
      if (!pressed) return;
      pressed = false;
      const body = start();
      body?.to("squash", 0, jelly(readFluidTokens(element, defaultMotion.fluid).wobble));
    };
    const move = (event: PointerEvent) => {
      if (entered || pressed || event.pointerType !== "mouse") return;
      entered = true;
      const body = start();
      if (!body) return;
      // Pointer speed (px/frame → px/s) relative to size becomes a squash impulse.
      const speed = Math.hypot(event.movementX, event.movementY) * 60;
      const size = Math.max(element.offsetWidth, element.offsetHeight, 1);
      const impulse = Math.min(1.6, (speed / size) * 0.08);
      body.to("squash", 0, jelly(readFluidTokens(element, defaultMotion.fluid).wobble), { velocity: impulse });
    };
    const leave = () => {
      entered = false;
      release();
    };

    element.addEventListener("pointerdown", down);
    element.addEventListener("pointermove", move);
    element.addEventListener("pointerleave", leave);
    window.addEventListener("pointerup", release);
    window.addEventListener("pointercancel", release);
    return () => {
      element.removeEventListener("pointerdown", down);
      element.removeEventListener("pointermove", move);
      element.removeEventListener("pointerleave", leave);
      window.removeEventListener("pointerup", release);
      window.removeEventListener("pointercancel", release);
    };
  }, [ref, enabled, driverFor, bodyFor]);
}

/**
 * Pop: when one of `attributes` turns on (e.g. `data-checked`), the element
 * grows from `from` with a jelly wobble; turning off gives a softer ripple.
 */
export function useFluidPop(
  ref: React.RefObject<HTMLElement | null>,
  { attributes, target, from = 0.7, motion }: { attributes: string[]; target?: React.RefObject<HTMLElement | null>; from?: number; motion?: MotionProp },
) {
  const animated = target ?? ref;
  const driverFor = useFluidDriver(motion);
  const bodyFor = useBody(animated);
  const was = React.useRef<boolean | null>(null);

  useAttributeChange(ref, attributes, () => {
    const element = ref.current;
    const subject = animated.current;
    if (!element || !subject) return;
    const on = attributes.some((name) => element.hasAttribute(name));
    if (was.current === on) return;
    was.current = on;
    const driver = driverFor(subject);
    if (!driver) return;
    const body = bodyFor(driver);
    const { wobble } = readFluidTokens(subject, defaultMotion.fluid);
    if (on) {
      body.to("sx", 1, getSpring("fluid", "spatial", "fast"), { from });
      body.to("sy", 1, getSpring("fluid", "spatial", "fast"), { from });
      body.to("squash", 0, jelly(wobble), { velocity: 1.4 });
    } else {
      body.to("squash", 0, jelly(wobble), { velocity: -0.8 });
    }
  });

  React.useEffect(() => {
    const element = ref.current;
    if (element) was.current = attributes.some((name) => element.hasAttribute(name));
    // Mark the subject so `fluid:` classes apply from the start.
    if (animated.current) driverFor(animated.current);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
}

/**
 * Layout: when one of `attributes` changes, the element jumps to its new
 * layout and then springs there from where it was (FLIP). On the way it
 * stretches with speed, leans into the motion, and wobbles as it settles.
 */
export function useFluidLayout(
  ref: React.RefObject<HTMLElement | null>,
  { attributes, motion }: { attributes: string[]; motion?: MotionProp },
) {
  const driverFor = useFluidDriver(motion);
  const bodyFor = useBody(ref);
  const layout = React.useRef<{ cx: number; cy: number; w: number; h: number } | null>(null);

  const measure = (element: HTMLElement) => ({
    cx: element.offsetLeft + element.offsetWidth / 2,
    cy: element.offsetTop + element.offsetHeight / 2,
    w: element.offsetWidth,
    h: element.offsetHeight,
  });

  useAttributeChange(ref, attributes, () => {
    const element = ref.current;
    if (!element) return;
    const previous = layout.current;
    const driver = driverFor(element); // also sets data-fluid, disabling CSS layout transitions
    const next = measure(element);
    layout.current = next;
    if (!driver || !previous) return;
    const body = bodyFor(driver);
    const { pose } = body;
    const spring = getSpring("fluid", "spatial", "default");
    body.to("x", 0, spring, { from: previous.cx + pose.x - next.cx });
    body.to("y", 0, spring, { from: previous.cy + pose.y - next.cy });
    if (next.w > 0 && next.h > 0) {
      body.to("sx", 1, spring, { from: (previous.w * pose.sx) / next.w });
      body.to("sy", 1, spring, { from: (previous.h * pose.sy) / next.h });
    }
  });

  React.useEffect(() => {
    const element = ref.current;
    if (!element) return;
    layout.current = measure(element);
    driverFor(element);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
}

/**
 * Entrance for elements that mount when opened (dialog popups): returns a
 * callback ref; each time an element attaches, it swells in from `from` with a
 * jelly settle.
 */
export function useFluidEnter({ from = 0.6, motion }: { from?: number; motion?: MotionProp } = {}) {
  const driverFor = useFluidDriver(motion);
  const body = React.useRef<FluidBody | null>(null);
  return React.useCallback(
    (element: HTMLElement | null) => {
      body.current?.stop();
      body.current = null;
      if (!element) return;
      const driver = driverFor(element);
      if (!driver) return;
      const entering = new FluidBody(element, driver);
      body.current = entering;
      const spring = getSpring("fluid", "spatial", "default");
      entering.to("sx", 1, spring, { from });
      entering.to("sy", 1, spring, { from: from * 0.85 });
      entering.to("y", 0, spring, { from: 24 });
      entering.to("squash", 0, jelly(readFluidTokens(element, defaultMotion.fluid).wobble), { velocity: -1.2 });
    },
    [driverFor, from],
  );
}

/** Combine refs (ours + the caller's). */
export function useComposedRef<T>(...refs: Array<React.Ref<T> | undefined>) {
  // eslint-disable-next-line react-hooks/exhaustive-deps
  return React.useCallback((node: T | null) => {
    for (const ref of refs) {
      if (typeof ref === "function") ref(node);
      else if (ref) (ref as React.RefObject<T | null>).current = node;
    }
  }, refs);
}
